####################################################################################################
# Imports

import csv
import math
from pathlib import Path


####################################################################################################
# Constants

DATA_FILE = Path(__file__).parent / "data" / "simulated_flight.csv"

FREEFALL_THRESHOLD_G = 0.4
FREEFALL_CONFIRM_SAMPLES = 3
MAX_RECOVERY_RESPONSE_MS = 3000.0

EXPECTED_PHASES = [
    "PRE_LAUNCH",
    "ASCENT",
    "FREEFALL",
    "DESCENT",
    "LANDED",
]


####################################################################################################
# Utility Functions

def load_data():
    if not DATA_FILE.exists():
        raise FileNotFoundError(
            f"{DATA_FILE} does not exist. Run simulate_flight.py first."
        )

    with DATA_FILE.open("r", newline="") as file:
        return list(csv.DictReader(file))


def acceleration_magnitude(row):
    ax = float(row["accel_x_g"])
    ay = float(row["accel_y_g"])
    az = float(row["accel_z_g"])

    return math.sqrt(ax * ax + ay * ay + az * az)


def check(condition, message):
    if not condition:
        raise AssertionError(message)

    print(f"[PASS] {message}")


####################################################################################################
# Tests

def test_dataset(rows):
    check(len(rows) > 0, "Dataset contains samples")

    phases = [row["expected_phase"] for row in rows]

    for phase in EXPECTED_PHASES:
        check(phase in phases, f"{phase} phase exists")

    phase_order = []

    for phase in phases:
        if not phase_order or phase_order[-1] != phase:
            phase_order.append(phase)

    check(
        phase_order == EXPECTED_PHASES,
        "Mission phases occur in correct order",
    )


def test_ascent(rows):
    ascent = [
        row for row in rows
        if row["expected_phase"] == "ASCENT"
    ]

    check(len(ascent) > 0, "Ascent contains samples")

    max_altitude = max(float(row["altitude_m"]) for row in ascent)

    check(
        95.0 <= max_altitude <= 105.0,
        f"Ascent reaches approximately 100 m ({max_altitude:.2f} m)",
    )


def test_freefall_and_recovery_conditions(rows):
    consecutive = 0
    first_low_g_time = None
    trigger_time = None

    for row in rows:
        magnitude = acceleration_magnitude(row)
        time_s = float(row["time_s"])

        if magnitude < FREEFALL_THRESHOLD_G:

            if consecutive == 0:
                first_low_g_time = time_s

            consecutive += 1

            if consecutive >= FREEFALL_CONFIRM_SAMPLES:
                trigger_time = time_s
                break

        else:
            consecutive = 0
            first_low_g_time = None

    check(
        trigger_time is not None,
        "Dataset contains at least 3 consecutive low-g samples",
    )

    response_ms = (trigger_time - first_low_g_time) * 1000.0

    check(
        response_ms <= MAX_RECOVERY_RESPONSE_MS,
        f"Expected recovery confirmation is within 3000 ms ({response_ms:.1f} ms)",
    )

    print(
        f"       First low-g sample : {first_low_g_time:.3f} s\n"
        f"       Trigger sample     : {trigger_time:.3f} s\n"
        f"       Confirmation delay : {response_ms:.1f} ms"
    )


def test_descent_and_landing(rows):
    descent = [
        row for row in rows
        if row["expected_phase"] == "DESCENT"
    ]

    landed = [
        row for row in rows
        if row["expected_phase"] == "LANDED"
    ]

    check(len(descent) > 0, "Descent contains samples")
    check(len(landed) > 0, "Landing contains samples")

    descent_start = float(descent[0]["altitude_m"])
    descent_end = float(descent[-1]["altitude_m"])

    check(
        descent_start > descent_end,
        "Altitude decreases during descent",
    )

    landing_altitudes = [
        float(row["altitude_m"])
        for row in landed
    ]

    average_landing_altitude = (
        sum(landing_altitudes) / len(landing_altitudes)
    )

    check(
        average_landing_altitude < 1.0,
        f"Landing altitude returns near ground ({average_landing_altitude:.2f} m)",
    )


def test_gnss(rows):
    for row in rows:
        latitude = float(row["latitude"])
        longitude = float(row["longitude"])

        check(
            -90.0 <= latitude <= 90.0,
            "GNSS latitude is valid",
        )

        check(
            -180.0 <= longitude <= 180.0,
            "GNSS longitude is valid",
        )

        break


def test_environmental_values(rows):
    for row in rows:
        check(
            float(row["pressure_pa"]) > 0.0,
            "Pressure values are positive",
        )

        check(
            float(row["pm1_ugm3"]) >= 0.0
            and float(row["pm25_ugm3"]) >= 0.0
            and float(row["pm10_ugm3"]) >= 0.0,
            "Particulate values are non-negative",
        )

        check(
            float(row["lux1"]) >= 0.0
            and float(row["lux2"]) >= 0.0
            and float(row["lux3"]) >= 0.0,
            "Light values are non-negative",
        )

        break


####################################################################################################
# Main

def main():
    print("\nCONSCIENTIA SIL - Simulated Flight Validation")
    print("=" * 52)

    rows = load_data()

    test_dataset(rows)
    test_ascent(rows)
    test_freefall_and_recovery_conditions(rows)
    test_descent_and_landing(rows)
    test_gnss(rows)
    test_environmental_values(rows)

    print("=" * 52)
    print("ALL SIMULATED FLIGHT TESTS PASSED")


if __name__ == "__main__":
    main()